-- ============================================================================
-- B5 FOLLOW-ON W5 (section 3 pick B, strip): welldesign. The W1 open-book label
-- comes off the brief of each tier below.
--
-- WHY. W1 (D4 C) labelled these briefs open book because a lesson, a panel's
-- opening view or the page printed some graded answers. Those prints are gone
-- (NextGen zip; src/components/course/panels/welldesign/capstoneLeak.test.jsx
-- proves each tier prints none and runs a negative control), so the label is
-- no longer true.
--
-- beginner:
--   the survey listing opened on the feet golden well (TVD and vertical section
--   graded); it now opens on the 131-station teaching well
-- advanced:
--   the clearance ladder opened on offset 10 (its minimum separation factor
--   graded) and the page intro printed that factor to three decimals; the ladder
--   now opens on offset 05 and the intro prints two decimals
--
-- WHAT MOVES. The brief's first sentence (the label). The brief becomes exactly
-- its text before W1.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after, so no answer grades
-- differently and there is no attempts guard (pick B keeps the keys).
--
-- GUARDS. Each brief must hold its W1-labelled text (md5, rewritten) or its
-- unlabelled text (left alone), with the fields this file was generated
-- against. Anything else raises and the file rolls back. The file refuses
-- unless W1 is applied. Generated by docs/graded-field-audit/w5d_capstones.py.
-- SAFE TO RE-RUN.
--
-- AFTER THIS FILE, 20261024b_w1_openbook_welldesign.sql reads these tiers as its
-- "published" form again and would put the label back: it is SUPERSEDED and
-- must not be re-applied (/root/w5d-apply/apply.sh reports it so).
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
  v_s1       text;
begin
  -- W1 (20261024*) must be applied: before it, an unlabelled brief is not evidence of anything
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'gasprocessing' and c.tier = 'beginner' and c.active
                    and f->>'key' = 'tegReboilerMMBtuHr') then
    raise exception 'w5d welldesign refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  -- welldesign / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'welldesign' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w5d welldesign refused: welldesign/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '443db164c59e8310153d45aff2f3b8a1' and fields = '[{"key": "ade_mincurve_tvd", "tol": 0.002, "unit": "ft", "label": "ADE chapter 8 minimum-curvature TVD", "expected": 1653.986686265376}, {"key": "ade_tangential_tvd_error", "tol": 0.005, "unit": "ft", "label": "Tangential TVD less published value", "expected": -25.38120586938976}, {"key": "golden_ft_tvd", "tol": 0.005, "unit": "ft", "label": "Feet well TVD at total depth", "expected": 3686.9804661202493}, {"key": "golden_ft_vertical_section", "tol": 0.005, "unit": "ft", "label": "Feet well vertical section", "expected": 1255.8726308373678}, {"key": "golden_m_north", "tol": 0.005, "unit": "m", "label": "Metric well north displacement", "expected": -1320.505235386686}, {"key": "buildhold_end_tvd", "tol": 0.005, "unit": "ft", "label": "Compiled build-and-hold end TVD", "expected": 1481.1257260785915}]'::jsonb then 'old'
              when md5(prompt) = '2d542668d8922a5d989e70fa751efd79' and fields = '[{"key": "ade_mincurve_tvd", "tol": 0.002, "unit": "ft", "label": "ADE chapter 8 minimum-curvature TVD", "expected": 1653.986686265376}, {"key": "ade_tangential_tvd_error", "tol": 0.005, "unit": "ft", "label": "Tangential TVD less published value", "expected": -25.38120586938976}, {"key": "golden_ft_tvd", "tol": 0.005, "unit": "ft", "label": "Feet well TVD at total depth", "expected": 3686.9804661202493}, {"key": "golden_ft_vertical_section", "tol": 0.005, "unit": "ft", "label": "Feet well vertical section", "expected": 1255.8726308373678}, {"key": "golden_m_north", "tol": 0.005, "unit": "m", "label": "Metric well north displacement", "expected": -1320.505235386686}, {"key": "buildhold_end_tvd", "tol": 0.005, "unit": "ft", "label": "Compiled build-and-hold end TVD", "expected": 1481.1257260785915}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'welldesign' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w5d welldesign refused: welldesign/beginner matches neither its W1-labelled form (prompt md5 443db164c59e8310153d45aff2f3b8a1) nor its stripped form (prompt md5 2d542668d8922a5d989e70fa751efd79), with the fields this file was generated against';
  end if;

  -- welldesign / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'welldesign' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w5d welldesign refused: welldesign/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '58320c07b0166e2c4c46909a2467a2b6' and fields = '[{"key": "well01_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 01", "expected": 1.400242036710446}, {"key": "well09_min_sf", "tol": 0.00005, "unit": "-", "label": "Minimum separation factor, offset 09", "expected": 0.009794688844024428}, {"key": "well10_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 10", "expected": -0.6068571428571429}, {"key": "well10_min_sf_at_k5", "tol": 0.0005, "unit": "-", "label": "Offset 10 minimum at k of 5.0", "expected": -0.4248}, {"key": "wmm_max_declination_error_deg", "tol": 0.000005, "unit": "deg", "label": "Worst declination error, 12 points", "expected": 0.00461482429820137}, {"key": "wmm_declination_at_80n_0e", "tol": 0.00005, "unit": "deg", "label": "Declination at 80N 0E, epoch 2025.0", "expected": 1.2814821161348655}]'::jsonb then 'old'
              when md5(prompt) = 'd83bf1f1b460e034b729b0251b51a08e' and fields = '[{"key": "well01_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 01", "expected": 1.400242036710446}, {"key": "well09_min_sf", "tol": 0.00005, "unit": "-", "label": "Minimum separation factor, offset 09", "expected": 0.009794688844024428}, {"key": "well10_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 10", "expected": -0.6068571428571429}, {"key": "well10_min_sf_at_k5", "tol": 0.0005, "unit": "-", "label": "Offset 10 minimum at k of 5.0", "expected": -0.4248}, {"key": "wmm_max_declination_error_deg", "tol": 0.000005, "unit": "deg", "label": "Worst declination error, 12 points", "expected": 0.00461482429820137}, {"key": "wmm_declination_at_80n_0e", "tol": 0.00005, "unit": "deg", "label": "Declination at 80N 0E, epoch 2025.0", "expected": 1.2814821161348655}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'welldesign' and tier = 'advanced' and active;
  if v_s1 = 'other' then
    raise exception 'w5d welldesign refused: welldesign/advanced matches neither its W1-labelled form (prompt md5 58320c07b0166e2c4c46909a2467a2b6) nor its stripped form (prompt md5 d83bf1f1b460e034b729b0251b51a08e), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already stripped
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w5d welldesign: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six survey calculations on three fixtures. (1) On the Applied Drilling Engineering chapter 8 survey, compute the full minimum-curvature survey table and report the true vertical depth at the deepest station. (2) On that same survey, compute the tangential method''s true vertical depth, summing over intervals the interval length times the cosine of the inclination at the LOWER station of each interval, and report that value MINUS the published minimum-curvature true vertical depth of 1653.99 ft. The published value is the reference, not the engine''s own answer. (3) On the FEET golden well, report the true vertical depth at total depth. (4) On that same well, report the vertical section at total depth, using the fixture''s own reference azimuth of 75 degrees rather than any default. (5) On the METRIC golden well, using its stated reference azimuth of 200 degrees, report the north displacement at total depth; it is negative. (6) Compile the first published build-and-hold design, kicking off vertical, building at the stated rate to the stated inclination and holding for the stated length on the stated azimuth, and report the true vertical depth at the last row of the compiled table.'
     where app_slug = 'welldesign' and tier = 'beginner' and active and md5(prompt) = '443db164c59e8310153d45aff2f3b8a1';
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w5d welldesign refused: welldesign/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '2d542668d8922a5d989e70fa751efd79' and fields = '[{"key": "ade_mincurve_tvd", "tol": 0.002, "unit": "ft", "label": "ADE chapter 8 minimum-curvature TVD", "expected": 1653.986686265376}, {"key": "ade_tangential_tvd_error", "tol": 0.005, "unit": "ft", "label": "Tangential TVD less published value", "expected": -25.38120586938976}, {"key": "golden_ft_tvd", "tol": 0.005, "unit": "ft", "label": "Feet well TVD at total depth", "expected": 3686.9804661202493}, {"key": "golden_ft_vertical_section", "tol": 0.005, "unit": "ft", "label": "Feet well vertical section", "expected": 1255.8726308373678}, {"key": "golden_m_north", "tol": 0.005, "unit": "m", "label": "Metric well north displacement", "expected": -1320.505235386686}, {"key": "buildhold_end_tvd", "tol": 0.005, "unit": "ft", "label": "Compiled build-and-hold end TVD", "expected": 1481.1257260785915}]'::jsonb) from public.academy_capstones where app_slug = 'welldesign' and tier = 'beginner' and active) is not true then
    raise exception 'w5d welldesign refused: welldesign/beginner does not read back as its stripped form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Six numbers from the ISCWSA standard clearance set and the geomagnetic model. Use the published clearance parameters throughout: pedal-curve method, confidence factor 3.5, surface position sigma 0.5 m, tool projection allowance 0.3 m, reference hole radius 0.4572 m, offset hole radius 0.3048 m, and the ISCWSA MWD Rev4 error model with each well''s own header from the fixture. Report: (1) the MINIMUM separation factor over the reference well''s stations against offset 01; (2) the same against offset 09, which is very nearly zero; (3) the same against offset 10, the only case with a kickoff, supplying the kickoff depth the fixture states so the shared uncertainty above it is removed; it is NEGATIVE. (4) Rerun case 3 with the confidence factor raised to 5.0 and nothing else changed, and report that minimum. Compute it by rerunning rather than by scaling field 3. (5) Evaluate the WMM2025 model at each of the publisher''s twelve test points and report the LARGEST absolute declination error in degrees, a maximum and not a mean. (6) Report the declination the model gives at 80 degrees north, 0 degrees east, at sea level, at the epoch 2025.0.'
     where app_slug = 'welldesign' and tier = 'advanced' and active and md5(prompt) = '58320c07b0166e2c4c46909a2467a2b6';
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w5d welldesign refused: welldesign/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'd83bf1f1b460e034b729b0251b51a08e' and fields = '[{"key": "well01_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 01", "expected": 1.400242036710446}, {"key": "well09_min_sf", "tol": 0.00005, "unit": "-", "label": "Minimum separation factor, offset 09", "expected": 0.009794688844024428}, {"key": "well10_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 10", "expected": -0.6068571428571429}, {"key": "well10_min_sf_at_k5", "tol": 0.0005, "unit": "-", "label": "Offset 10 minimum at k of 5.0", "expected": -0.4248}, {"key": "wmm_max_declination_error_deg", "tol": 0.000005, "unit": "deg", "label": "Worst declination error, 12 points", "expected": 0.00461482429820137}, {"key": "wmm_declination_at_80n_0e", "tol": 0.00005, "unit": "deg", "label": "Declination at 80N 0E, epoch 2025.0", "expected": 1.2814821161348655}]'::jsonb) from public.academy_capstones where app_slug = 'welldesign' and tier = 'advanced' and active) is not true then
    raise exception 'w5d welldesign refused: welldesign/advanced does not read back as its stripped form';
  end if;

  raise notice 'w5d welldesign: % of 2 row(s) written, % already applied', v_written, 2 - v_written;
end $$;
